package io.relational.runner;

import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.sql.*; import java.util.*;

final class WorkflowRunner {
  private final Cli cli; private final Manifest manifest;
  WorkflowRunner(Cli cli, Manifest manifest){this.cli=cli;this.manifest=manifest;}
  void execute() throws Exception {
    List<ManifestEntry> entries=manifest.entries().stream().filter(ManifestEntry::enabled).filter(e->cli.from()==null||e.seq()>=cli.from()).filter(e->cli.through()==null||e.seq()<=cli.through()).toList();
    validate(entries); System.out.printf("Manifest: %s%nMode: %s%nArtifacts: %d%n",manifest.manifestPath(),cli.dryRun()?"DRY RUN":"RUN",entries.size());
    if(cli.dryRun()){ for(var e:entries) System.out.printf("[%04d] %-8s %s%n",e.seq(),e.kind(),e.artifactPath()); System.out.println("Dry run successful."); return; }
    try(Connection c=Db.connect()){ c.setAutoCommit(false); for(var e:entries){System.out.printf("[%04d] %-8s %s ... ",e.seq(),e.kind(),e.artifactPath()); try{ switch(e.kind()){case SQL->sql(c,e);case VERIFY->verify(c,e);case EXPORT->export(c,e);case LOAD_CSV->loadCsv(c,e);} c.commit(); System.out.println("OK");}catch(Exception ex){c.rollback();System.out.println("FAILED");throw ex;} } }
    System.out.println("Workflow completed successfully.");
  }
  private void validate(List<ManifestEntry> entries) throws IOException { for(var e:entries){ Path a=manifest.resolve(e.artifactPath()); if(a==null||!Files.isRegularFile(a))throw new IllegalArgumentException("Artifact not found for seq "+e.seq()+": "+e.artifactPath()); if(e.kind()==ArtifactKind.LOAD_CSV){if(e.sourcePath().isBlank()||e.targetTable().isBlank())throw new IllegalArgumentException("LOAD_CSV requires source_path and target_table at seq "+e.seq()); Path s=manifest.resolve(e.sourcePath());if(!Files.isRegularFile(s))throw new IllegalArgumentException("CSV not found: "+e.sourcePath());} if(e.kind()==ArtifactKind.EXPORT&&e.outputPath().isBlank())throw new IllegalArgumentException("EXPORT requires output_path at seq "+e.seq()); if(!e.outputPath().isBlank())manifest.resolve(e.outputPath()); } }
  private void sql(Connection c,ManifestEntry e)throws Exception{try(Statement st=c.createStatement()){for(String s:SqlScripts.statements(manifest.resolve(e.artifactPath())))st.execute(s);}}
  private void verify(Connection c,ManifestEntry e)throws Exception{List<String> q=SqlScripts.statements(manifest.resolve(e.artifactPath()));if(q.size()!=1)throw new IllegalArgumentException("VERIFY must contain exactly one query: "+e.artifactPath());try(Statement st=c.createStatement();ResultSet rs=st.executeQuery(q.get(0))){if(rs.next())throw new IllegalStateException("Verification failed at seq "+e.seq()+": query returned rows");}}
  private void export(Connection c,ManifestEntry e)throws Exception{List<String> q=SqlScripts.statements(manifest.resolve(e.artifactPath()));if(q.size()!=1)throw new IllegalArgumentException("EXPORT must contain exactly one query");Path out=manifest.resolve(e.outputPath());Files.createDirectories(out.getParent());try(Statement st=c.createStatement();ResultSet rs=st.executeQuery(q.get(0));BufferedWriter w=Files.newBufferedWriter(out,StandardCharsets.UTF_8)){ResultSetMetaData md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++){if(i>1)w.write(',');w.write(Csv.escape(md.getColumnLabel(i)));}w.newLine();while(rs.next()){for(int i=1;i<=md.getColumnCount();i++){if(i>1)w.write(',');w.write(Csv.escape(rs.getString(i)));}w.newLine();}}}
  private void loadCsv(Connection c,ManifestEntry e)throws Exception{List<List<String>> spec=Csv.read(manifest.resolve(e.artifactPath())), data=Csv.read(manifest.resolve(e.sourcePath()));if(spec.size()<2||data.isEmpty())throw new IllegalArgumentException("Invalid CSV spec/input at seq "+e.seq());Map<String,Integer> specH=index(spec.get(0)), dataH=index(data.get(0));List<String> cols=new ArrayList<>(), headers=new ArrayList<>();List<Boolean> required=new ArrayList<>();for(int i=1;i<spec.size();i++){var r=spec.get(i);String sh=cell(r,specH,"source_header"), col=cell(r,specH,"column_name");if(!dataH.containsKey(sh))throw new IllegalArgumentException("Missing CSV header '"+sh+"' in "+e.sourcePath());headers.add(sh);cols.add(col);required.add(cell(r,specH,"required").trim().equalsIgnoreCase("Y"));}
    String table=identifier(e.targetTable());try(Statement st=c.createStatement()){st.executeUpdate("TRUNCATE TABLE "+table);}String sql="INSERT INTO "+table+" ("+String.join(",",cols.stream().map(WorkflowRunner::identifier).toList())+") VALUES ("+String.join(",",Collections.nCopies(cols.size(),"?"))+")";try(PreparedStatement ps=c.prepareStatement(sql)){int batch=0;for(int r=1;r<data.size();r++){var row=data.get(r);for(int i=0;i<headers.size();i++){String v=cell(row,dataH,headers.get(i));if(required.get(i)&&v.isBlank())throw new IllegalArgumentException("Required value missing: "+headers.get(i)+" row "+(r+1));if(v.isBlank())ps.setNull(i+1,Types.VARCHAR);else ps.setString(i+1,v);}ps.addBatch();if(++batch%1000==0)ps.executeBatch();}ps.executeBatch();}}
  private static Map<String,Integer> index(List<String> h){Map<String,Integer>m=new HashMap<>();for(int i=0;i<h.size();i++)m.put(h.get(i),i);return m;} private static String cell(List<String>r,Map<String,Integer>h,String n){Integer i=h.get(n);return i==null||i>=r.size()?"":r.get(i);} private static String identifier(String s){if(s==null||!s.matches("[A-Za-z][A-Za-z0-9_$#]*"))throw new IllegalArgumentException("Unsafe Oracle identifier: "+s);return s.toUpperCase(Locale.ROOT);}
}
